import base64,zlib,hashlib,json,subprocess,sys,os
from pathlib import Path
p=Path("/home/featurize/work/bigearth_soft43_20261011_01")
assert not p.exists(), "Output exists: preserve and inspect"
process=subprocess.Popen([sys.executable,"-B","-u","-c",'import base64,zlib,hashlib,json; s=zlib.decompress(base64.b64decode(\'\')); assert hashlib.sha256(s).hexdigest()==\'6e47784ff9e3f4f85c99fd205d5a7c8dc5c04606bc0e1520b93bf14f41b533b4\'; ns={"__name__":"frozen_handoff"}; exec(compile(s,"<frozen_handoff>","exec"),ns); print("READYJSON "+json.dumps(ns["report"]),flush=True)'],stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
ready=None
for line in process.stdout:
    if line.startswith("READYJSON "):
        ready=json.loads(line[len("READYJSON "):])
    else:
        print(line,end="",flush=True)
assert process.wait()==0 and ready is not None, "Preflight failed: no training started"
assert ready["status"]=="BIGEARTH_SOFT43_PREFLIGHT_PASS"
s=zlib.decompress(base64.b64decode(""))
check=zlib.decompress(base64.b64decode(""))
assert hashlib.sha256(s).hexdigest()=="37f05738b8fc99e20e95d4c84ba8392f8707b1175e58c838725fd34a40b0a07e" and hashlib.sha256(check).hexdigest()=="6e47784ff9e3f4f85c99fd205d5a7c8dc5c04606bc0e1520b93bf14f41b533b4"
p.mkdir()
(p/"preflight.py").write_bytes(check)
(p/"approved_preflight.json").write_text(json.dumps(ready,indent=2)+"\n")
f=p/"run_bigearth_soft43.py"
f.write_bytes(s)
with (p/"run.log").open("xb") as log:
    q=subprocess.Popen([sys.executable,"-B","-u",str(f),str(p)],stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT,start_new_session=True,env={**os.environ,"OMP_NUM_THREADS":"8","MKL_NUM_THREADS":"8","PYTHONDONTWRITEBYTECODE":"1"})
(p/"run.pid").write_text(str(q.pid)+"\n")
print("PID",q.pid,"OUTPUT",p,flush=True)
